"use client";
import LegacyPage from "../components/LegacyPage";

const TITLE = "Averages — Grades";
const STYLE_CSS = "\n  /* ---------- Shared design system — copied verbatim from /courses\n     so this page reads as the same app, not a reskin. See\n     architecture-decisions.md for the note about promoting this to an\n     actual shared stylesheet once there's a build step. ---------- */\n  :root {\n    --accent: #d94a2b;\n    --accent-dark: #a8331a;\n    --accent-ring: rgb(from var(--accent) r g b / 0.35);\n    --page-bg-start: #f17b53;\n    --page-bg-end: #930500;\n    --panel-bg: #eaeaec;\n    --panel-inner: #dcdce0;\n    --text-dark: #14151f;\n    --text-muted: #4b4d63;\n    --text-faint: #83849a;\n    --border: #cfcfd6;\n    --window-radius-lg: 22px;\n    --window-radius-md: 14px;\n    --window-radius-sm: 10px;\n    --grade-good: #2f7d54;\n    --grade-mid: #a67a22;\n    --grade-bad: #b6432f;\n    /* A/B/C/D/F letter-grade color scale (2026-08-31, per Martin's\n       request) — see gradeBand()/GRADE_COLOR below. A and C reuse the\n       existing good/mid tokens (already \"green\"/\"amber\"), F reuses bad\n       (\"red\"); B and D are new in-between stops. */\n    --grade-b: #5c8a3f;\n    --grade-d: #c1602f;\n  }\n\n  * { box-sizing: border-box; }\n\n  /* Scrollbars app-wide: a slim, permanently-visible, rounded gray bar\n     sitting slightly inset from the true edge of its scrollable area --\n     like a normal OS/Gmail-style scrollbar, not hidden and not\n     hover-gated. (An earlier hover-only version turned out unreliable:\n     the outer page counts as \"hovered\" almost the entire time you're\n     using it, so it either showed constantly or never, depending on the\n     browser -- not the meaningful hover signal it needed to be.)\n     Scrolling itself always works via wheel/trackpad/touch/keys either\n     way. One universal rule (the `*` selector) so it covers every\n     scrollable element automatically — the outer page scroll, every\n     popup/modal, every internal list — without repeating it per\n     element. (The bottom nav's own horizontal scroll strip is a\n     deliberate exception — see .app-nav-inner further down — that one\n     stays permanently hidden as a mobile overflow safety net.) */\n  * {\n    scrollbar-width: thin;\n    scrollbar-color: rgba(20, 21, 31, 0.28) transparent;\n  }\n  *::-webkit-scrollbar { width: 10px; height: 10px; }\n  *::-webkit-scrollbar-track { background: transparent; }\n  *::-webkit-scrollbar-thumb {\n    background-color: rgba(20, 21, 31, 0.28);\n    border-radius: 999px;\n    border: 2px solid transparent;\n    background-clip: padding-box; /* the transparent border creates the\n      inset gap around the thumb, so it reads as sitting inside the\n      window rather than flush against the very edge */\n  }\n  *::-webkit-scrollbar-thumb:hover { background-color: rgba(20, 21, 31, 0.45); }\n  *::-webkit-scrollbar-corner { background: transparent; }\n\n  /* Declared so the browser themes ITS OWN chrome — scrollbars, the\n\n     overscroll gutter, form controls — against this page rather than\n\n     guessing. Without it Firefox drew a light-theme scrollbar over the\n\n     dark canvas and tinted it (Martin saw it as pink on a blue\n\n     background). LegacyPage's applyStoredTheme() updates both of these\n\n     to match whatever background the user actually saved. */\n\n  html {\n\n    color-scheme: dark;\n\n    background-color: #0c0c0e;\n\n  }\n\n\n  html, body {\n    margin: 0;\n    padding: 0;\n    min-height: 100%;\n    font-family: \"puffin\", -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif;\n  }\n\n  body {\n    height: 100vh; /* fixed, not min -- body itself no longer scrolls */\n    overflow: hidden; /* scrolling now happens inside .page (see below), so\n      the scrollbar sits at the edge of the app's own window/card instead of\n      out at the browser's outer edge, over the wallpaper margin */\n    /* Neutral black instead of a baked-in accent gradient here —\n       2026-09-11, per Martin. This is only ever visible for a split\n       second on reload/navigation, before applyStoredTheme() (or this\n       page's own appearance-reading script) sets the user's actual\n       saved background over it. The old default was the sample\n       red-orange gradient baked into this file, which read as a real\n       glitch flashing in between pages; a neutral black reads as\n       \"still loading\" instead, and matches the app's own Black\n       preset (#0c0c0e) so it's not a color that appears nowhere else\n       in the app. */\n    background-color: #0c0c0e;\n    background-image: none;\n    background-size: cover;\n    background-position: center;\n    background-repeat: no-repeat;\n    padding: 40px 24px 100px;\n    display: flex;\n    justify-content: center;\n  }\n\n  .page {\n    width: 100%;\n    max-width: 980px;\n    align-self: stretch; /* fill body's available height regardless of\n      whatever align-items body declares, so there's a bounded box to\n      scroll within */\n    min-height: 0; /* flexbox gotcha: without this, a flex item won't\n      shrink below its content size, which breaks overflow scrolling */\n    overflow-y: auto; /* the actual scroll happens here -- .card grows to\n      its natural content height and .page scrolls as a whole */\n    overflow-x: hidden;\n  }\n\n  /* ---------- Top bar ---------- */\n  .topbar {\n    display: flex;\n    align-items: flex-end;\n    justify-content: space-between;\n    margin: 0 4px 18px;\n  }\n\n  h1.title {\n    color: #ffffff;\n    font-size: clamp(1.6rem, 3.4vw, 2.1rem);\n    font-weight: 900;\n    font-style: italic;\n    letter-spacing: -0.01em;\n    margin: 0;\n    transform: skewX(-2deg);\n    display: inline-block;\n  }\n  .subtitle {\n    color: rgba(255,255,255,0.85);\n    font-weight: 700;\n    font-style: italic;\n    font-size: 0.9rem;\n    margin: 2px 0 0 2px;\n  }\n\n  .profile-menu-wrap { position: relative; flex-shrink: 0; }\n  .profile-btn {\n    width: 42px;\n    height: 42px;\n    border-radius: 50%;\n    background: rgba(255,255,255,0.2);\n    border: 2px solid rgba(255,255,255,0.5);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    color: #fff;\n    font-weight: 800;\n    font-size: 0.95rem;\n    cursor: pointer;\n    flex-shrink: 0;\n  }\n  .profile-menu {\n    position: absolute;\n    top: calc(100% + 10px);\n    right: 0;\n    min-width: 160px;\n    background: var(--panel-bg);\n    border-radius: var(--window-radius-md);\n    box-shadow: 0 20px 45px -16px rgba(0,0,0,0.5);\n    padding: 6px;\n    z-index: 25;\n  }\n  .profile-menu-item {\n    display: block;\n    width: 100%;\n    text-align: left;\n    background: none;\n    border: none;\n    border-radius: var(--window-radius-sm);\n    font: inherit;\n    font-weight: 700;\n    font-size: 0.86rem;\n    color: var(--text-dark);\n    padding: 9px 12px;\n    cursor: pointer;\n  }\n  .profile-menu-item:hover { background: var(--panel-inner); }\n  .profile-menu-item.signout { color: var(--grade-bad); }\n\n  /* ---------- One card, same as every other page ---------- */\n  .card {\n    background: var(--panel-bg);\n    border-radius: var(--window-radius-lg);\n    padding: 6px;\n  }\n  .card-inner {\n    padding: 22px 24px 8px;\n  }\n\n  .section-head {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    margin-bottom: 4px;\n  }\n  .section-head h2 {\n    font-size: 1rem;\n    font-weight: 800;\n    font-style: italic;\n    color: var(--text-dark);\n    margin: 0;\n  }\n  .section-head .course-total {\n    font-size: 0.76rem;\n    font-weight: 700;\n    color: var(--text-faint);\n  }\n\n  /* ---------- Estimated GPA strip (2026-09-01, per Martin) — a quick\n     unweighted 4.0-scale summary above the per-course table, using each\n     course's current letter grade (not predicted). Colored via the same\n     red-through-green idiom as everything else on this page rather than\n     a flat accent color, so a glance at the number alone hints at how\n     it's trending overall. The \"what does this number mean\" explanation\n     used to sit inline as permanent small text next to the value; per\n     Martin it's now a hover/focus tooltip on the \"Estimated GPA\" label\n     instead (.gpa-tooltip below), same lightweight idiom as a native\n     title attribute but styled to match the rest of the app. ---------- */\n  .gpa-strip {\n    display: flex;\n    align-items: baseline;\n    gap: 10px;\n    flex-wrap: wrap;\n    padding-bottom: 16px;\n    margin-bottom: 4px;\n    border-bottom: 1px solid var(--border);\n  }\n  .gpa-label-wrap { position: relative; display: inline-block; cursor: help; }\n  .gpa-label { font-size: 0.66rem; font-weight: 800; text-transform: uppercase; letter-spacing: 0.05em; color: var(--text-faint); }\n  .gpa-value { font-size: 1.7rem; font-weight: 900; font-style: italic; line-height: 1; }\n  .gpa-tooltip {\n    position: absolute;\n    left: 0;\n    bottom: calc(100% + 9px);\n    width: 200px;\n    background: var(--panel-bg);\n    color: var(--text-dark);\n    font-size: 0.72rem;\n    font-weight: 600;\n    text-transform: none;\n    letter-spacing: normal;\n    line-height: 1.4;\n    padding: 9px 11px;\n    border-radius: var(--window-radius-sm);\n    box-shadow: 0 16px 34px -14px rgba(0,0,0,0.5);\n    opacity: 0;\n    visibility: hidden;\n    transform: translateY(4px);\n    transition: opacity 0.12s ease, transform 0.12s ease;\n    pointer-events: none;\n    z-index: 30;\n  }\n  .gpa-label-wrap:hover .gpa-tooltip,\n  .gpa-label-wrap:focus-visible .gpa-tooltip { opacity: 1; visibility: visible; transform: translateY(0); }\n  @media (prefers-reduced-motion: reduce) { .gpa-tooltip { transition: none; } }\n  @media (max-width: 560px) {\n    .gpa-strip { flex-direction: column; gap: 2px; }\n  }\n\n  /* ---------- Grades table ---------- */\n  table.grades-table {\n    width: 100%;\n    border-collapse: collapse;\n    margin-top: 14px;\n  }\n  table.grades-table thead th {\n    text-align: left;\n    font-size: 0.66rem;\n    font-weight: 800;\n    text-transform: uppercase;\n    letter-spacing: 0.04em;\n    color: var(--text-faint);\n    padding: 0 8px 10px;\n    border-bottom: 1px solid var(--border);\n  }\n  table.grades-table thead th:not(:first-child) { text-align: center; }\n  table.grades-table tbody td {\n    padding: 13px 8px;\n    border-bottom: 1px solid var(--border);\n    font-size: 0.85rem;\n    color: var(--text-dark);\n    vertical-align: middle;\n  }\n  table.grades-table tbody tr:last-child td { border-bottom: none; }\n  table.grades-table tbody td:not(:first-child) { text-align: center; }\n  table.grades-table tbody tr { cursor: pointer; }\n  table.grades-table tbody tr:hover td { background: var(--panel-inner); }\n  table.grades-table tbody tr:hover td:first-child { border-top-left-radius: var(--window-radius-sm); border-bottom-left-radius: var(--window-radius-sm); }\n  table.grades-table tbody tr:hover td:last-child { border-top-right-radius: var(--window-radius-sm); border-bottom-right-radius: var(--window-radius-sm); }\n\n  /* Class column — same tick + name/code/meta idiom as /courses so\n     this reads as sourced from the same PowerSchool/Schoology data. */\n  .course-row { display: flex; align-items: flex-start; gap: 10px; }\n  .course-tick { width: 4px; align-self: stretch; min-height: 34px; border-radius: 999px; flex-shrink: 0; margin-top: 1px; }\n  .course-row-text { min-width: 0; }\n  .course-row-top { display: flex; align-items: baseline; gap: 7px; flex-wrap: wrap; }\n  .course-row-name { font-weight: 700; font-size: 0.86rem; color: var(--text-dark); }\n  .course-row-code { font-weight: 700; font-size: 0.7rem; color: var(--text-faint); letter-spacing: 0.01em; }\n  .course-row-meta {\n    display: flex;\n    align-items: center;\n    gap: 4px;\n    font-size: 0.72rem;\n    color: var(--text-muted);\n    margin-top: 2px;\n  }\n  .course-row-meta svg { width: 11px; height: 11px; flex-shrink: 0; color: var(--text-faint); }\n\n  .grade-val { font-weight: 800; font-size: 0.9rem; }\n  .grade-val.a { color: var(--grade-good); }\n  .grade-val.b { color: var(--grade-b); }\n  .grade-val.c { color: var(--grade-mid); }\n  .grade-val.d { color: var(--grade-d); }\n  .grade-val.f { color: var(--grade-bad); }\n  .grade-pct { display: block; font-weight: 600; font-size: 0.68rem; color: var(--text-faint); margin-top: 1px; }\n\n  .trend { display: inline-flex; align-items: center; justify-content: center; gap: 3px; font-weight: 700; font-size: 0.82rem; color: var(--text-muted); border-radius: 6px; padding: 3px 7px; }\n  .trend .arrow { display: inline-flex; align-items: center; justify-content: center; width: 13px; font-weight: 800; font-size: 0.95rem; transform: translateY(1px); }\n  .trend.up { background: rgba(47, 125, 84, 0.14); }\n  .trend.down { background: rgba(182, 67, 47, 0.14); }\n  .trend.flat { background: rgba(131, 132, 154, 0.14); }\n  .trend.up .arrow { color: var(--grade-good); }\n  .trend.down .arrow { color: var(--grade-bad); }\n  .trend.flat .arrow { color: var(--text-faint); transform: translateY(-3px); }\n  .trend .grade-pct { display: inline; margin-top: 0; margin-left: 2px; }\n\n  /* Predicted-grade cell doubles as a hover/focus target for the same\n     reasoning popup /home//courses's Grades table has — ported\n     over verbatim per the established convention. */\n  .trend.has-popup { cursor: help; }\n  .trend.has-popup:hover,\n  .trend.has-popup:focus-visible { filter: brightness(0.94); }\n  .trend.has-popup:focus-visible {\n    outline: none;\n    box-shadow: 0 0 0 2px var(--accent-ring);\n  }\n\n  /* ---------- Predicted-grade reasoning popup — copied verbatim from\n     /courses's .grade-popup. ---------- */\n  .grade-popup {\n    position: fixed;\n    z-index: 50;\n    width: 272px;\n    background: var(--panel-bg);\n    border-radius: var(--window-radius-md);\n    box-shadow: 0 22px 48px -16px rgba(0,0,0,0.5);\n    padding: 14px 16px 10px;\n    opacity: 0;\n    visibility: hidden;\n    transform: translateY(4px);\n    transition: opacity 0.12s ease, transform 0.12s ease;\n    pointer-events: none;\n  }\n  .grade-popup.show {\n    opacity: 1;\n    visibility: visible;\n    transform: translateY(0);\n    pointer-events: auto;\n  }\n  .grade-popup h3 {\n    margin: 0 0 2px;\n    font-size: 0.82rem;\n    font-weight: 800;\n    color: var(--text-dark);\n  }\n  .grade-popup .popup-sub {\n    font-size: 0.7rem;\n    color: var(--text-muted);\n    margin: 0 0 8px;\n    line-height: 1.4;\n  }\n  .grade-popup .popup-sub strong { color: var(--text-dark); }\n  .grade-popup svg { display: block; overflow: visible; }\n  .grade-popup .popup-foot {\n    font-size: 0.62rem;\n    color: var(--text-faint);\n    margin: 6px 0 0;\n    text-align: right;\n    font-style: italic;\n  }\n\n  @media (prefers-reduced-motion: reduce) {\n    .grade-popup { transition: none; }\n  }\n\n  /* Grade Calculator column — a quiet ghost pill (not accent-filled like\n     a primary CTA) since it's a secondary action alongside the row's own\n     \"open the gradebook\" click; a calculator glyph makes its purpose\n     legible without needing the word to compete with the Predicted\n     column's own text at this width. */\n  /* The whole cell is a click target now (2026-09-03), not just the pill\n     itself — see the JS click-handler comment for why. */\n  .calc-cell { cursor: pointer; }\n\n  .calc-btn {\n    display: inline-flex;\n    align-items: center;\n    gap: 6px;\n    background: var(--panel-inner);\n    border: 1px solid var(--border);\n    border-radius: 999px;\n    padding: 6px 13px 6px 10px;\n    font-family: inherit;\n    font-weight: 800;\n    font-size: 0.72rem;\n    color: var(--text-dark);\n    cursor: pointer;\n  }\n  .calc-btn svg { width: 13px; height: 13px; stroke: currentColor; fill: none; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; flex-shrink: 0; }\n  .calc-btn:hover { background: var(--accent); border-color: var(--accent); color: #fff; }\n  .calc-btn:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); }\n\n  @media (max-width: 560px) {\n    table.grades-table thead { display: none; }\n    table.grades-table, table.grades-table tbody, table.grades-table tbody tr, table.grades-table tbody td { display: block; width: 100%; }\n    table.grades-table tbody tr { padding: 10px 4px; border-bottom: 1px solid var(--border); }\n    table.grades-table tbody td { border-bottom: none; padding: 6px 4px; text-align: left !important; }\n    table.grades-table tbody tr:last-child { border-bottom: none; }\n    .grade-val, .trend { display: inline-flex; }\n    .grade-val .grade-pct { display: inline; margin: 0 0 0 4px; }\n    table.grades-table tbody td:nth-child(2)::before { content: 'Grade: '; font-size: 0.7rem; font-weight: 700; color: var(--text-faint); display: block; margin-bottom: 2px; }\n    table.grades-table tbody td:nth-child(3)::before { content: 'Predicted: '; font-size: 0.7rem; font-weight: 700; color: var(--text-faint); display: block; margin-bottom: 2px; }\n    .calc-btn { width: 100%; justify-content: center; }\n    /* The desktop hover treatment above (a shaded background rounded only\n       on the row's outer corners, so a single horizontal row reads as one\n       rounded pill) leaves stray rounded-corner artifacts once the row's\n       cells stack into separate full-width blocks here: each cell now\n       renders its own hover background, but only ever rounds two of its\n       own four corners (the ones meant for the far-left/far-right edge of\n       a desktop row) — so a small rounded nub shows up mid-card, at the\n       bottom of the Class cell and the top of the Grade Calculator cell,\n       with nothing to visually connect it to. Touch browsers make this\n       worse by keeping :hover \"stuck\" after a tap until something else is\n       tapped, so the artifact can sit there persistently rather than only\n       flashing by under a mouse. Simplest correct fix: the per-row hover\n       shading doesn't read as one coherent shape once stacked, so it's\n       turned off at this breakpoint rather than patched corner-by-corner. */\n    table.grades-table tbody tr:hover td { background: none; }\n    table.grades-table tbody tr:hover td:first-child,\n    table.grades-table tbody tr:hover td:last-child { border-radius: 0; }\n  }\n\n  /* ---------- Bottom nav — copied verbatim from /courses. ---------- */\n  .app-nav {\n    position: fixed;\n    left: 0;\n    right: 0;\n    bottom: 20px;\n    display: flex;\n    justify-content: center;\n    padding: 0 20px;\n    z-index: 10;\n    pointer-events: none;\n  }\n  .app-nav-inner {\n    display: flex;\n    gap: 4px;\n    width: 100%;\n    max-width: 940px;\n    overflow-x: auto;\n    scrollbar-width: none;\n    background: var(--panel-bg);\n    border-radius: var(--window-radius-md);\n    padding: 0 8px;\n    pointer-events: auto;\n  }\n  .app-nav-inner::-webkit-scrollbar { display: none; }\n  .nav-link {\n    background: none;\n    border: none;\n    cursor: pointer;\n    font-family: inherit;\n    flex: 1;\n    min-width: 0;\n    padding: 12px 6px 10px;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    gap: 5px;\n  }\n  .nav-link .label { display: block; max-width: 100%; font-size: 0.72rem; font-weight: 800; color: var(--text-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; text-align: center; }\n  .nav-link:hover .label { color: var(--text-muted); }\n  .nav-link .dot { width: 4px; height: 4px; border-radius: 50%; background: transparent; }\n  .nav-link.active .label { color: var(--text-dark); }\n  .nav-link.active .dot { background: var(--accent); }\n  /* ---------- \"More\" overflow (2026-10-01, per Martin: \"if the text has\n     to get ... we should add a more button on the far right side with a\n     list of the other options\"). Labels never truncate: when they would,\n     the rightmost pages move into the More menu instead. ---------- */\n  .nav-link[hidden], .nav-more[hidden], .nav-more-menu[hidden] { display: none; }\n  /* While the More menu is open the whole bar sits above everything else on\n     the page (sticky headers, pop-ups, the edit button go up to z-index 90),\n     so the menu is never drawn underneath them. */\n  .app-nav.more-open { z-index: 1000; }\n  .nav-more {\n    background: none;\n    border: none;\n    cursor: pointer;\n    font-family: inherit;\n    flex: 0 0 auto;\n    position: relative;\n    margin-left: 4px;\n    padding: 12px 16px 10px;\n    display: flex;\n    flex-direction: column;\n    align-items: center;\n    gap: 5px;\n  }\n  .nav-more .label { display: flex; align-items: center; height: 1.2em; font-size: 0.72rem; color: var(--text-faint); }\n  .nav-more .label svg { display: block; fill: currentColor; }\n  /* thin divider between the pages and the dots */\n  .nav-more::before { content: \"\"; position: absolute; left: 0; top: 12px; bottom: 12px; width: 1px; background: var(--border, #cfcfd6); }\n  .nav-more:hover .label, .nav-more[aria-expanded=\"true\"] .label { color: var(--text-dark); }\n  .nav-more .dot { width: 4px; height: 4px; border-radius: 50%; background: transparent; }\n  .nav-more.has-active .label { color: var(--text-dark); }\n  .nav-more.has-active .dot { background: var(--accent); }\n  .nav-more:focus-visible { outline: none; box-shadow: 0 0 0 3px var(--accent-ring) inset; }\n  .nav-more-menu {\n    position: absolute;\n    bottom: calc(100% + 8px);\n    right: 20px;\n    min-width: 168px;\n    padding: 8px;\n    display: flex;\n    flex-direction: column;\n    gap: 4px;\n    background: var(--panel-bg);\n    border-radius: var(--window-radius-md);\n    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.18);\n    pointer-events: auto;\n  }\n  .nav-more-item {\n    background: none;\n    border: none;\n    cursor: pointer;\n    font-family: inherit;\n    font-size: 0.8rem;\n    font-weight: 800;\n    color: var(--text-faint);\n    text-align: left;\n    padding: 12px 12px;\n    border-radius: 8px;\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    gap: 12px;\n  }\n  .nav-more-item:hover, .nav-more-item:focus-visible { outline: none; color: var(--text-dark); box-shadow: 0 0 0 3px var(--accent-ring) inset; }\n  .nav-more-item.active { color: var(--text-dark); }\n  .nav-more-item.active span { position: relative; display: inline-block; padding-bottom: 6px; margin-bottom: -6px; }\n  .nav-more-item.active span::after { content: \"\"; position: absolute; left: 0; right: 0; bottom: 0; height: 3px; border-radius: 999px; background: var(--accent); }\n  /* Labels sit centered in the bar; the active page is underlined in the\n     accent color instead of marked with a dot (2026-10-01, per Martin). */\n  .app-nav-inner .nav-link, .app-nav-inner .nav-more { justify-content: center; gap: 0; padding-top: 10px; padding-bottom: 10px; }\n  .app-nav-inner .nav-link .dot, .app-nav-inner .nav-more .dot { display: none; }\n  .app-nav-inner .nav-link .label, .app-nav-inner .nav-more .label { position: relative; padding: 6px 0; }\n  .app-nav-inner .nav-link.active .label::after, .app-nav-inner .nav-more.has-active .label::after { content: \"\"; position: absolute; left: 0; right: 0; bottom: 0; height: 3px; border-radius: 999px; background: var(--accent); }\n  @media (max-width: 520px) {\n    .nav-more { padding: 10px 12px 8px; }\n    .nav-more::before { top: 10px; bottom: 10px; }\n    .app-nav-inner .nav-link, .app-nav-inner .nav-more { padding-top: 8px; padding-bottom: 8px; }\n    .nav-more .label { font-size: 0.58rem; }\n  }\n  .nav-link:focus-visible { outline: none; box-shadow: 0 0 0 3px var(--accent-ring) inset; }\n  @media (max-width: 520px) {\n    .nav-link { min-width: 0; padding: 10px 3px 8px; }\n    .nav-link .label { font-size: 0.58rem; }\n  }\n\n  /* ---------- Modal shell — copied from /course-home's course-info\n     pop-out (fade + slide-up show/hide, X close button), widened for the\n     Grade Calculator content this page needs. (Used to also back a\n     read-only Gradebook pop-out here — removed 2026-08-31, see the\n     Grade Calculator note further down: clicking a course row now\n     navigates straight to the real /gradebook instead.) ---------- */\n  .modal-overlay {\n    position: fixed; inset: 0; background: rgba(10, 8, 6, 0.55);\n    display: flex; align-items: center; justify-content: center;\n    padding: 20px; z-index: 60;\n    opacity: 0; visibility: hidden; transition: opacity 0.15s ease;\n  }\n  .modal-overlay.show { opacity: 1; visibility: visible; }\n  .modal-box {\n    background: var(--panel-bg);\n    border-radius: var(--window-radius-lg);\n    max-width: 380px; width: 100%;\n    padding: 22px 24px;\n    box-shadow: 0 30px 70px -20px rgba(0,0,0,0.6);\n    transform: translateY(8px);\n    transition: transform 0.15s ease;\n  }\n  .modal-overlay.show .modal-box { transform: translateY(0); }\n  /* .wide (the Grade Calculator) scrolls internally — the scrolling has\n     to happen on an inner wrapper (.modal-box-scroll), not this element\n     itself, or the browser's native scrollbar renders at this box's flat\n     edge and pokes out past its own rounded corners (reported 2026-09-01\n     by Martin — a screenshot showed the scrollbar thumb sticking out\n     above/below the modal). This element now just clips (overflow:\n     hidden + the border-radius it already had) and un-pads itself so all\n     padding — and the actual overflow-y: auto — moves to the inner div,\n     whose content therefore never draws past the rounded corner. */\n  .modal-box.wide { max-width: 520px; max-height: 85vh; overflow: hidden; padding: 0; }\n  .modal-box-scroll { max-height: 85vh; overflow-y: auto; padding: 22px 24px; }\n  .modal-close {\n    float: right;\n    background: var(--panel-inner);\n    border: none;\n    width: 26px; height: 26px;\n    border-radius: 50%;\n    color: var(--text-muted);\n    cursor: pointer;\n    font-size: 0.9rem;\n    line-height: 1;\n  }\n  .modal-close:hover { color: var(--text-dark); }\n  .modal-box h3 { margin: 2px 0 2px; font-size: 1.1rem; font-weight: 900; font-style: italic; color: var(--text-dark); }\n  .modal-code { font-size: 0.76rem; font-weight: 700; color: var(--text-faint); margin: 0 0 4px; }\n\n  /* Grade Calculator */\n  .calc-hero {\n    text-align: center;\n    background: var(--panel-inner);\n    border-radius: var(--window-radius-md);\n    padding: 14px 10px 12px;\n    margin: 14px 0 16px;\n  }\n  .calc-hero .calc-hero-label { font-size: 0.66rem; font-weight: 800; text-transform: uppercase; letter-spacing: 0.04em; color: var(--text-faint); }\n  .calc-hero .calc-hero-val { font-size: 1.9rem; font-weight: 900; font-style: italic; margin-top: 2px; }\n  .calc-hero .calc-hero-pct { font-size: 0.85rem; font-weight: 700; color: var(--text-muted); margin-left: 6px; font-style: normal; }\n  .calc-category { margin-bottom: 14px; }\n  .calc-category-head {\n    display: flex;\n    align-items: baseline;\n    justify-content: space-between;\n    margin-bottom: 6px;\n  }\n  .calc-category-name { font-weight: 800; font-size: 0.82rem; color: var(--text-dark); }\n  .calc-category-weight { font-size: 0.7rem; font-weight: 700; color: var(--text-faint); }\n  /* Signed in with nothing to list (2026-10-06). */\n  .calc-empty { margin: 14px 0 4px; font-size: 0.8rem; font-weight: 700; color: var(--text-faint); }\n  .calc-assign-row {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    gap: 10px;\n    padding: 5px 0;\n    font-size: 0.78rem;\n  }\n  .calc-assign-title { color: var(--text-dark); font-weight: 600; }\n  .calc-assign-score { color: var(--text-muted); font-weight: 700; white-space: nowrap; }\n  .calc-input {\n    width: 48px;\n    padding: 4px 6px;\n    border-radius: 7px;\n    border: 1px solid var(--border);\n    background: var(--panel-bg);\n    color: var(--text-dark);\n    font-family: inherit;\n    font-weight: 700;\n    font-size: 0.78rem;\n    text-align: right;\n    /* Extra breathing room before the \"/ out-of-points\" text next to it\n       (2026-09-01, per Martin) — the input and its label used to sit\n       flush against each other. */\n    margin-right: 6px;\n  }\n  .calc-input:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); }\n  .calc-input.hyp { background: rgba(217, 74, 43, 0.08); border-color: var(--accent); }\n  /* Fixed width (2026-09-01, per Martin: the score boxes didn't line up\n     into a clean column) — without this, \"/ 5\" vs \"/ 50\" are different\n     text widths, and since .calc-assign-score is pinned to the row's\n     right edge, that difference pushed the input box itself left or\n     right row to row. A fixed-width label keeps every input's left edge\n     in the same column regardless of how many digits the point value has. */\n  .calc-out-of { display: inline-block; width: 30px; text-align: left; color: var(--text-muted); font-weight: 700; }\n  .calc-divider { border: none; border-top: 1px solid var(--border); margin: 14px 0; }\n  /* Final Exam mini-calculator (reworked 2026-09-01, per Martin, to match\n     a reference \"Final Grade Calculator\" tool he shared) — used to be\n     gated behind an \"Include a hypothetical final assessment\" checkbox\n     with an explanatory paragraph; both are gone. The three fields are\n     always visible and always live: Current grade / Grade you want /\n     Final exam weight, solving for the score still needed rather than\n     projecting a score forward like the category inputs above do. */\n  .calc-final-heading { font-weight: 800; font-size: 0.82rem; color: var(--text-dark); margin: 0 0 8px; }\n  .calc-final-inputs { display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 10px; }\n  .calc-final-field { flex: 1 1 100px; min-width: 90px; }\n  .calc-final-field label { display: block; font-size: 0.66rem; font-weight: 800; text-transform: uppercase; letter-spacing: 0.03em; color: var(--text-faint); margin-bottom: 4px; }\n  .calc-final-field input {\n    width: 100%;\n    padding: 7px 9px;\n    border-radius: var(--window-radius-sm);\n    border: 1px solid var(--border);\n    background: var(--panel-bg);\n    color: var(--text-dark);\n    font-family: inherit;\n    font-weight: 700;\n    font-size: 0.82rem;\n    box-sizing: border-box;\n  }\n  .calc-final-field input:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); }\n  .calc-final-answer {\n    background: var(--panel-inner);\n    border-radius: var(--window-radius-sm);\n    padding: 10px 12px;\n    font-size: 0.8rem;\n    font-weight: 600;\n    color: var(--text-dark);\n    line-height: 1.45;\n    margin: 0 0 4px;\n    min-height: 1.2em;\n  }\n  .calc-final-answer:empty { display: none; }\n  .calc-actions { display: flex; justify-content: flex-end; margin-top: 16px; }\n  .calc-reset-btn {\n    background: var(--panel-inner);\n    border: 1px solid var(--border);\n    border-radius: 999px;\n    padding: 8px 15px;\n    font-family: inherit;\n    font-weight: 800;\n    font-size: 0.76rem;\n    color: var(--text-dark);\n    cursor: pointer;\n  }\n  .calc-reset-btn:hover { background: var(--border); }\n  .calc-reset-btn:focus-visible { outline: none; box-shadow: 0 0 0 2px var(--accent-ring); }\n";
const BODY_HTML = "\n  <div class=\"page\">\n    <div class=\"topbar\">\n      <div>\n        <h1 class=\"title\">Your Grades</h1>\n        <p class=\"subtitle\" id=\"courseCountSub\">6 classes</p>\n      </div>\n      <div class=\"profile-menu-wrap\">\n        <button class=\"profile-btn\" id=\"profileBtn\" type=\"button\" aria-haspopup=\"menu\" aria-expanded=\"false\" aria-label=\"Profile and settings\">M</button>\n        <div class=\"profile-menu\" id=\"profileMenu\" role=\"menu\" hidden>\n          <button class=\"profile-menu-item\" type=\"button\" role=\"menuitem\" data-action=\"settings\">Settings</button>\n          <button class=\"profile-menu-item signout\" type=\"button\" role=\"menuitem\" data-action=\"signout\">Sign out</button>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"card-inner\">\n        <div class=\"gpa-strip\">\n          <span class=\"gpa-label-wrap\" tabindex=\"0\" role=\"button\" aria-label=\"Estimated GPA — Unweighted, 4.0 scale, based on current grades\">\n            <span class=\"gpa-label\">Estimated GPA</span>\n            <span class=\"gpa-tooltip\" role=\"tooltip\">Unweighted, 4.0 scale, based on current grades</span>\n          </span>\n          <span class=\"gpa-value\" id=\"gpaValue\"></span>\n        </div>\n        <div class=\"section-head\">\n          <h2>All Courses</h2>\n          <span class=\"course-total\" id=\"courseTotal\"></span>\n        </div>\n        <table class=\"grades-table\">\n          <thead>\n            <tr>\n              <th>Class</th>\n              <th>Grade</th>\n              <th>Predicted Grade</th>\n              <th>Grade Calculator</th>\n            </tr>\n          </thead>\n          <tbody id=\"gradesBody\"></tbody>\n        </table>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"grade-popup\" id=\"gradePopup\" role=\"tooltip\"></div>\n\n  <nav class=\"app-nav\" aria-label=\"Main navigation\">\n    <div class=\"app-nav-inner\" id=\"dock\">\n      <button class=\"nav-link\" type=\"button\" data-page=\"home\" data-href=\"/home\">\n        <span class=\"label\">Home</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"courses\" data-href=\"/courses\">\n        <span class=\"label\">Courses</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link active\" type=\"button\" data-page=\"grades\">\n        <span class=\"label\">Grades</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"assignments\" data-href=\"/assignments\">\n        <span class=\"label\">Assignments</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"files\" data-href=\"/files\">\n        <span class=\"label\">Files</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"calendar\" data-href=\"/calendar\">\n        <span class=\"label\">Calendar</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"messages\" data-href=\"/messages\">\n        <span class=\"label\">Messages</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"contacts\" data-href=\"/contacts\">\n        <span class=\"label\">Contacts</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-link\" type=\"button\" data-page=\"settings\" data-href=\"/settings\">\n        <span class=\"label\">Settings</span>\n        <span class=\"dot\"></span>\n      </button>\n      <button class=\"nav-more\" type=\"button\" id=\"navMore\" aria-haspopup=\"menu\" aria-expanded=\"false\" aria-controls=\"navMoreMenu\" aria-label=\"More pages\" hidden>\n        <span class=\"label\"><svg viewBox=\"0 0 16 4\" width=\"16\" height=\"4\" aria-hidden=\"true\"><circle cx=\"2\" cy=\"2\" r=\"1.75\"/><circle cx=\"8\" cy=\"2\" r=\"1.75\"/><circle cx=\"14\" cy=\"2\" r=\"1.75\"/></svg></span>\n        <span class=\"dot\"></span>\n      </button>\n    </div>\n    <div class=\"nav-more-menu\" id=\"navMoreMenu\" role=\"menu\" aria-label=\"More pages\" hidden></div>\n  </nav>\n\n  \n\n\n  <!-- Final Grade Calculator — site-map.md's Final Grade Calculator spec:\n       imports the course's real gradebook, lets the user edit any\n       assignment's score (real or extra credit) to see the effect live,\n       plus a standalone Final Exam mini-calculator (2026-09-01 rework,\n       replacing an earlier checkbox-gated \"hypothetical final\" section)\n       that solves for the final exam score needed to hit a target grade. -->\n  <div class=\"modal-overlay\" id=\"calcModal\">\n    <div class=\"modal-box wide\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"calcCourseName\">\n      <div class=\"modal-box-scroll\">\n        <button class=\"modal-close\" id=\"calcCloseBtn\" type=\"button\" aria-label=\"Close grade calculator\">✕</button>\n        <h3 id=\"calcCourseName\"></h3>\n        <p class=\"modal-code\" id=\"calcCourseCode\">Final Grade Calculator</p>\n        <div class=\"calc-hero\">\n          <div class=\"calc-hero-label\" id=\"calcHeroLabel\">Current grade</div>\n          <div class=\"calc-hero-val\"><span id=\"calcHeroLetter\"></span><span class=\"calc-hero-pct\" id=\"calcHeroPct\"></span></div>\n        </div>\n        <div id=\"calcCategories\"></div>\n        <hr class=\"calc-divider\">\n        <h4 class=\"calc-final-heading\">Final Exam</h4>\n        <div class=\"calc-final-inputs\">\n          <div class=\"calc-final-field\">\n            <label for=\"calcFinalCurrent\">Current grade (%)</label>\n            <input type=\"number\" id=\"calcFinalCurrent\" min=\"0\" max=\"100\" step=\"0.1\">\n          </div>\n          <div class=\"calc-final-field\">\n            <label for=\"calcFinalWant\">Grade you want (%)</label>\n            <input type=\"number\" id=\"calcFinalWant\" min=\"0\" max=\"100\" step=\"0.1\" placeholder=\"e.g. 90\">\n          </div>\n          <div class=\"calc-final-field\">\n            <label for=\"calcFinalWeight\">Final exam weight (%)</label>\n            <input type=\"number\" id=\"calcFinalWeight\" min=\"1\" max=\"100\" value=\"20\">\n          </div>\n        </div>\n        <p class=\"calc-final-answer\" id=\"calcFinalAnswer\"></p>\n        <div class=\"calc-actions\">\n          <button class=\"calc-reset-btn\" id=\"calcResetBtn\" type=\"button\">Reset to real grades</button>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  \n  \n";
const SCRIPT_JS = "\n    // Potato PC Mode on every page (2026-10-04, per Martin). The saved\n    // setting turns off all CSS animations and transitions, makes animate()\n    // calls and smooth scrolling instant, and drops the slanted page title.\n    // Same code as app/lib/theme-boot.ts, which runs it before first paint in\n    // the app; this copy covers the preview and pages theme-boot skips.\n    (function () {\n    var POTATO_CSS = \"body.potato-mode,body.potato-mode *,body.potato-mode *::before,body.potato-mode *::after{animation:none!important;transition:none!important;scroll-behavior:auto!important;filter:none!important;text-shadow:none!important}html:has(body.potato-mode){scroll-behavior:auto!important}body.potato-mode,body.potato-mode *{font-family:system-ui,-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif!important}body.potato-mode h1.title{font-style:normal!important;transform:none!important}body.potato-mode .trend.has-popup:focus-visible{outline:2px solid currentColor;outline-offset:2px}\";\n    function potatoOn() { return !!(document.body && document.body.classList.contains(\"potato-mode\")); }\n    function applyPotato() {\n      var on = false;\n      try { on = (JSON.parse(localStorage.getItem(\"schoolagy_settings_options\") || \"{}\") || {}).potatoMode === true; } catch (e) {}\n      if (document.body) document.body.classList.toggle(\"potato-mode\", on);\n      if (!document.getElementById(\"potatoStyle\")) {\n        var st = document.createElement(\"style\");\n        st.id = \"potatoStyle\";\n        st.textContent = POTATO_CSS;\n        (document.head || document.documentElement).appendChild(st);\n      }\n      var EP = window.Element && Element.prototype;\n      if (EP && !EP.__potatoPatched) {\n        EP.__potatoPatched = true;\n        var anim = EP.animate;\n        if (anim) EP.animate = function (frames, opts) {\n          if (potatoOn()) opts = (typeof opts === \"number\" || opts == null) ? { duration: 0 } : Object.assign({}, opts, { duration: 0, delay: 0, endDelay: 0, iterations: 1 });\n          return anim.call(this, frames, opts);\n        };\n        var siv = EP.scrollIntoView;\n        if (siv) EP.scrollIntoView = function (arg) {\n          if (potatoOn() && arg && typeof arg === \"object\") arg = Object.assign({}, arg, { behavior: \"auto\" });\n          return siv.call(this, arg);\n        };\n        [\"scrollTo\", \"scrollBy\"].forEach(function (name) {\n          [EP, window].forEach(function (target) {\n            var fn = target[name];\n            if (!fn) return;\n            target[name] = function (a, b) {\n              if (potatoOn() && a && typeof a === \"object\") a = Object.assign({}, a, { behavior: \"auto\" });\n              return b === undefined ? fn.call(this, a) : fn.call(this, a, b);\n            };\n          });\n        });\n      }\n    }\n      applyPotato();\n      window.addEventListener('storage', function (e) { if (e.key === 'schoolagy_settings_options') applyPotato(); });\n    })();\n\n    // Bottom nav \"More\" overflow. Shows as many pages as fit without\n    // cutting a label off (\"Cour...\"); the rest go in the More menu.\n    // The current page always stays in the bar.\n    (function () {\n      const nav = document.querySelector('.app-nav');\n      const inner = nav && nav.querySelector('.app-nav-inner');\n      const more = document.getElementById('navMore');\n      const menu = document.getElementById('navMoreMenu');\n      if (!inner || !more || !menu) return;\n      const links = Array.from(inner.querySelectorAll('.nav-link'));\n\n      const cut = () =>\n        inner.scrollWidth > inner.clientWidth + 1 ||\n        links.some(l => !l.hidden && l.querySelector('.label').scrollWidth > l.querySelector('.label').clientWidth + 1);\n\n      function fit() {\n        closeMenu();\n        links.forEach(l => { l.hidden = false; });\n        more.hidden = true;\n        if (!cut()) return;\n        more.hidden = false;\n        // Hide from the right, but never the current page.\n        for (let i = links.length - 1; i >= 1 && cut(); i--) {\n          if (!links[i].classList.contains('active')) links[i].hidden = true;\n        }\n        const hidden = links.filter(l => l.hidden);\n        more.classList.toggle('has-active', hidden.some(l => l.classList.contains('active')));\n        menu.textContent = '';\n        hidden.forEach(l => {\n          const item = document.createElement('button');\n          item.type = 'button';\n          item.className = 'nav-more-item' + (l.classList.contains('active') ? ' active' : '');\n          item.setAttribute('role', 'menuitem');\n          const text = document.createElement('span'); text.textContent = l.querySelector('.label').textContent; item.appendChild(text);\n          item.addEventListener('click', () => { closeMenu(); l.click(); });\n          menu.appendChild(item);\n        });\n      }\n\n      function openMenu() {\n        const navBox = nav.getBoundingClientRect();\n        const innerBox = inner.getBoundingClientRect();\n        menu.style.right = Math.max(0, navBox.right - innerBox.right) + 'px';\n        menu.hidden = false;\n        nav.classList.add('more-open');\n        more.setAttribute('aria-expanded', 'true');\n        const first = menu.querySelector('.nav-more-item');\n        if (first) first.focus();\n      }\n      function closeMenu() {\n        if (menu.hidden) return;\n        menu.hidden = true;\n        nav.classList.remove('more-open');\n        more.setAttribute('aria-expanded', 'false');\n      }\n\n      more.addEventListener('click', e => {\n        e.stopPropagation();\n        menu.hidden ? openMenu() : closeMenu();\n      });\n      document.addEventListener('click', e => { if (!menu.contains(e.target)) closeMenu(); });\n      document.addEventListener('keydown', e => {\n        if (e.key === 'Escape' && !menu.hidden) { closeMenu(); more.focus(); }\n        if (!menu.hidden && (e.key === 'ArrowDown' || e.key === 'ArrowUp')) {\n          const items = Array.from(menu.querySelectorAll('.nav-more-item'));\n          const i = items.indexOf(document.activeElement);\n          const next = items[(i + (e.key === 'ArrowDown' ? 1 : -1) + items.length) % items.length];\n          if (next) { e.preventDefault(); next.focus(); }\n        }\n      });\n\n      fit();\n      if (window.ResizeObserver) new ResizeObserver(fit).observe(nav);\n      else window.addEventListener('resize', fit);\n      if (document.fonts && document.fonts.ready) document.fonts.ready.then(fit);\n    })();\n  \n\n\n    // ------------------------------------------------------------------\n    // Shared appearance (accent + background) — 2026-09-08, per Martin:\n    // \"wallpapers + accent colors don't save across pages.\" Settings'\n    // Appearance section (and onboarding's Theme step) are the only\n    // writers of schoolagy_appearance; every other real app page,\n    // including this one, applies whatever's saved there, read-only, on\n    // its own load — same shared-localStorage-record pattern already\n    // used for schoolagy_dark_mode/schoolagy_profile.\n    // ------------------------------------------------------------------\n    (function () {\n      function darken(hex, amount) {\n        const n = parseInt(hex.slice(1), 16);\n        const r = Math.max(0, ((n >> 16) & 255) * (1 - amount));\n        const g = Math.max(0, ((n >> 8) & 255) * (1 - amount));\n        const b = Math.max(0, (n & 255) * (1 - amount));\n        return '#' + [r, g, b].map(v => Math.round(v).toString(16).padStart(2, '0')).join('');\n      }\n      function applyAppearance() {\n        let saved = null;\n        try {\n          const raw = localStorage.getItem('schoolagy_appearance');\n          if (raw) saved = JSON.parse(raw);\n        } catch {}\n        if (!saved) return;\n        const root = document.documentElement.style;\n        if (saved.accent) {\n          root.setProperty('--accent', saved.accent);\n          root.setProperty('--accent-dark', saved.accentDark || darken(saved.accent, 0.22));\n        }\n        if (saved.background === 'white') {\n          document.body.style.backgroundImage = 'none';\n          document.body.style.backgroundColor = '#f4f4f6';\n        } else if (saved.background === 'black') {\n          document.body.style.backgroundImage = 'none';\n          document.body.style.backgroundColor = '#0c0c0e';\n        } else if (saved.background) {\n          document.body.style.backgroundImage = `url(\"${saved.background}\")`;\n          document.body.style.backgroundColor = '';\n        }\n      }\n      applyAppearance();\n      window.addEventListener('storage', e => {\n        if (e.key === 'schoolagy_appearance') applyAppearance();\n      });\n    })();\n\n    // ------------------------------------------------------------------\n    // Sample data — same six courses as /courses's COURSES array\n    // (same id/name/color/grade/predicted/updated values), trimmed to\n    // what this page's wireframe called for: Class, Grade, Predicted\n    // Grade, Grade Calculator. No Assignments/Updated columns here —\n    // those belong to the All Courses list, not the Grades overview.\n    // ------------------------------------------------------------------\n\n    // ------------------------------------------------------------------\n    // Course customization persistence — added 2026-09-08. Renaming,\n    // recoloring, or reordering a course (in /home's Customize editor\n    // or /courses's Reorder tool — the only places that WRITE these)\n    // used to be invisible everywhere else, since every page just\n    // re-generated its own hardcoded COURSES array from scratch on load.\n    // schoolagy_course_custom holds per-course name/color overrides\n    // (object keyed by course id, only actually-customized courses\n    // present); schoolagy_course_order holds a full custom ordering of\n    // course ids (array), written only once the user has actually\n    // reordered. This page only READS both — applyCourseCustomizationsInPlace()\n    // is called right after the raw array literal below, mutating COURSES\n    // in place, so it's already the customized/reordered version before\n    // anything on this page ever renders it. Same defensive\n    // try/catch-per-key style as AVERAGES_DARK_MODE_KEY in /settings.\n    // ------------------------------------------------------------------\n    const AVERAGES_COURSE_CUSTOM_KEY = 'schoolagy_course_custom';\n    const AVERAGES_COURSE_ORDER_KEY = 'schoolagy_course_order';\n    function loadCourseCustom() {\n      try {\n        const raw = localStorage.getItem(AVERAGES_COURSE_CUSTOM_KEY);\n        if (raw) return JSON.parse(raw);\n      } catch {}\n      return {};\n    }\n    function loadCourseOrder() {\n      try {\n        const raw = localStorage.getItem(AVERAGES_COURSE_ORDER_KEY);\n        if (raw) return JSON.parse(raw);\n      } catch {}\n      return null;\n    }\n    // Subject table (2026-10-01, per Martin): each course gets a color that\n    // fits its subject, picked from its name. First match wins, so specific\n    // subjects come before broad ones (\"Computer Science\" before \"Science\",\n    // \"Physical Education\" before \"Physics\"). A color the student picked in\n    // the course's info pop-up still wins over this. No match keeps the\n    // course's own color. All colors pass 4.5:1 with white text.\n    const COURSE_SUBJECTS = [\n      [/\\bchem/, '🧪', '#1b7f67'],\n      [/\\bbio|anatom|physiolog/, '🧬', '#387f33'],\n      [/\\bphysical ed|(^|[^a-z])p\\.?e\\.?($|[^a-z])|fitness|\\bweight/, '🏃', '#c2562b'],\n      [/\\bhealth/, '🩺', '#c0404a'],\n      [/\\bphysics/, '⚛️', '#4a56b8'],\n      [/astronom/, '🔭', '#3b3f8f'],\n      [/environment|\\bearth|geolog/, '🌍', '#2f7f63'],\n      [/robotic/, '🤖', '#55697d'],\n      [/computer|programming|coding|\\bcs[ap]?\\b|software/, '💻', '#2d6f8f'],\n      [/engineer/, '⚙️', '#6a6478'],\n      [/government|civics|politic/, '🏛️', '#2f4f8a'],\n      [/econ/, '📈', '#2e7d4f'],\n      [/psych/, '🧠', '#9a4583'],\n      [/geograph/, '🗺️', '#4c7a5a'],\n      [/histor/, '📜', '#9a5a2a'],\n      [/statistic|\\bstats?\\b/, '📊', '#2f72a8'],\n      [/geometr|\\btrig/, '📐', '#3e64b0'],\n      [/calc|algebra|\\bmath/, '🧮', '#2f5fb3'],\n      [/english|literature|\\blit\\b|writing|composition|language arts|reading/, '📖', '#a63a4f'],\n      [/spanish|french|german|chinese|mandarin|japanese|korean|latin|italian|\\basl\\b|sign language|language/, '🗣️', '#7a4fae'],\n      [/theat|drama/, '🎭', '#a3364b'],\n      [/music|band|choir|orchestra|chorus/, '🎵', '#6b48a8'],\n      [/photo/, '📷', '#4f5d6e'],\n      [/culinary|cooking|\\bfoods?\\b|nutrition/, '🍳', '#b05a26'],\n      [/\\barts?\\b|drawing|painting|ceramic|sculpt|design/, '🎨', '#b03f7a'],\n      [/business|marketing|accounting|financ/, '💼', '#3d5f6e'],\n      [/journalism|yearbook|newspaper/, '📰', '#5c5c6e'],\n      [/science/, '🔬', '#2b7b8c'],\n    ];\n    function courseSubject(name) {\n      const n = String(name || '').toLowerCase();\n      return COURSE_SUBJECTS.find(([re]) => re.test(n)) || null;\n    }\n\n    function applyCourseCustomizationsInPlace(courses) {\n      const custom = loadCourseCustom();\n      // Mutates each course object's own fields in place (never clones,\n      // never reassigns `courses` itself) so the `const COURSES = [...]`\n      // literal a few lines below stays exactly that — a literal array —\n      // for scripts/port-pages.mjs's data-overrides transform to match\n      // and rewrite for live Schoology data. This function only edits\n      // the array's contents/order after that binding already exists.\n      courses.forEach(c => {\n        const subject = courseSubject(c.name);\n        if (subject) c.color = subject[2];\n        Object.assign(c, custom[c.id] || {});\n      });\n      const order = loadCourseOrder();\n      if (order && order.length) {\n        const byId = new Map(courses.map(c => [c.id, c]));\n        const ordered = order.filter(id => byId.has(id)).map(id => byId.get(id));\n        // A course not present in the saved order (e.g. added to the demo\n        // data after the order was saved) still shows up, just appended.\n        courses.forEach(c => { if (!order.includes(c.id)) ordered.push(c); });\n        courses.splice(0, courses.length, ...ordered);\n      }\n    }\n    const COURSES = (window.__AVERAGES__ && window.__AVERAGES__.data && window.__AVERAGES__.data.COURSES) || [\n      { id: 'apchem', name: 'AP Chemistry', code: '76_M0431', period: 2, teacher: 'Alvarez', section: '1204', color: '#a67a22', grade: 'B+', pct: 87, predicted: 'A-', predictedPct: 91, trend: 'up' },\n      { id: 'algebra2', name: 'Algebra II', code: '76_S0512', period: 3, teacher: 'Whitfield', section: '1188', color: '#5b6ea3', grade: 'A', pct: 95, predicted: 'A', predictedPct: 95, trend: 'flat' },\n      { id: 'english10', name: 'English 10', code: '76_F0288', period: 4, teacher: 'Cho', section: '1350', color: '#6b8f5e', grade: 'C+', pct: 78, predicted: 'C', predictedPct: 74, trend: 'down' },\n      { id: 'ushistory', name: 'U.S. History', code: '76_R0367', period: 1, teacher: 'Bennett', section: '1092', color: '#a15c4f', grade: 'A-', pct: 91, predicted: 'A-', predictedPct: 91, trend: 'flat' },\n      { id: 'spanish3', name: 'Spanish III', code: '76_G0295', period: 5, teacher: 'Ortiz', section: '1417', color: '#8a6ba1', grade: 'B', pct: 84, predicted: 'B+', predictedPct: 88, trend: 'up' },\n      { id: 'pe', name: 'PE', code: '76_P0300', period: 6, teacher: 'Reyes', section: '1125', color: '#4f8c8a', grade: 'A', pct: 97, predicted: 'A', predictedPct: 97, trend: 'flat' },\n    ];\n    applyCourseCustomizationsInPlace(COURSES);\n    // Signed in (2026-10-05): what the API doesn't know about a class yet\n    // (code, period, teacher, section) is empty, never \"undefined\".\n    COURSES.forEach(c => { ['code', 'period', 'teacher', 'section'].forEach(k => { if (c[k] === undefined || c[k] === null) c[k] = ''; }); });\n    function courseMetaLine(c) {\n      const left = [c.period !== '' ? `Pd:${c.period}` : '', c.teacher].filter(Boolean).join(' ');\n      return [left, c.section].filter(Boolean).join(' - ');\n    }\n\n    function findCourse(id) { return COURSES.find(c => c.id === id); }\n\n    // Escapes a value for interpolation into an HTML string — safe both in\n    // text positions and inside quoted attribute values. Every `${...}`\n    // below carrying course, gradebook or assignment data must go through\n    // it: in the live app those strings come from teachers, so rendered raw\n    // into innerHTML a title like `<img src=x onerror=...>` executes in our\n    // own origin. Same helper as /home — see its comment for the full\n    // reasoning. Do NOT wrap values that are themselves markup (the chart\n    // fragments, CALC_ICON, calcAssignQualifier).\n    function escapeHtml(value) {\n      return String(value).replace(/[&<>\"']/g, ch => (\n        { '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[ch]\n      ));\n    }\n\n    // Assignment-score history behind the Predicted-grade reasoning\n    // popup — copied verbatim from /courses's HISTORY (same course\n    // ids, same predictedPct/trend values).\n    const HISTORY = (window.__AVERAGES__ && window.__AVERAGES__.data && window.__AVERAGES__.data.HISTORY) || {\n      apchem: { points: [72, 79, 84, 88, 90], dates: ['Aug 4', 'Aug 8', 'Aug 12', 'Aug 18', 'Aug 24'] },\n      algebra2: { points: [94, 96, 93, 97, 95], dates: ['Aug 3', 'Aug 7', 'Aug 11', 'Aug 17', 'Aug 23'] },\n      english10: { points: [88, 82, 79, 76, 73], dates: ['Aug 4', 'Aug 8', 'Aug 12', 'Aug 18', 'Aug 24'] },\n      ushistory: { points: [89, 93, 88, 92, 90], dates: ['Aug 4', 'Aug 8', 'Aug 12', 'Aug 18', 'Aug 24'] },\n      spanish3: { points: [76, 80, 83, 85, 87], dates: ['Aug 3', 'Aug 7', 'Aug 11', 'Aug 17', 'Aug 23'] },\n      pe: { points: [96, 98, 95, 97, 96], dates: ['Aug 2', 'Aug 6', 'Aug 10', 'Aug 16', 'Aug 22'] },\n    };\n\n    // ------------------------------------------------------------------\n    // Gradebook data — new for this page. Each course's real weighted\n    // category breakdown, feeding both the read-only Gradebook pop-out\n    // and the editable Grade Calculator below. `graded:false` entries\n    // are what the Calculator's \"what-if\" score inputs apply to; the\n    // rest are locked-in real scores. Category weights always sum to\n    // 100 per course, matching a real Schoology-style weighted gradebook.\n    // ------------------------------------------------------------------\n    const GRADEBOOK = (window.__AVERAGES__ && window.__AVERAGES__.data && window.__AVERAGES__.data.GRADEBOOK) || {\n      apchem: { categories: [\n        { name: 'Tests', weight: 40, assignments: [\n          { title: 'Unit 1 Test', score: 42, points: 50, graded: true },\n          { title: 'Unit 2 Test', score: 45, points: 50, graded: true },\n        ]},\n        { name: 'Labs', weight: 30, assignments: [\n          { title: 'Titration Lab', score: 18, points: 20, graded: true },\n          { title: 'Lab Report #3', score: 17, points: 20, graded: true },\n          { title: 'Lab Report #4', points: 20, graded: false },\n        ]},\n        { name: 'Homework', weight: 30, assignments: [\n          { title: 'Problem Set 1', score: 9, points: 10, graded: true },\n          { title: 'Problem Set 2', score: 8, points: 10, graded: true },\n          { title: 'Problem Set 3', score: 10, points: 10, graded: true },\n        ]},\n      ]},\n      algebra2: { categories: [\n        { name: 'Tests', weight: 50, assignments: [\n          { title: 'Unit 2 Test', score: 47, points: 50, graded: true },\n          { title: 'Unit 3 Test', score: 48, points: 50, graded: true },\n        ]},\n        { name: 'Quizzes', weight: 30, assignments: [\n          { title: 'Quiz 4', score: 9, points: 10, graded: true },\n          { title: 'Quiz 5', score: 10, points: 10, graded: true },\n          { title: 'Quiz 6', points: 10, graded: false },\n        ]},\n        { name: 'Homework', weight: 20, assignments: [\n          { title: 'Problem Set 6', score: 10, points: 10, graded: true },\n          { title: 'Problem Set 7', score: 9, points: 10, graded: true },\n        ]},\n      ]},\n      english10: { categories: [\n        { name: 'Essays', weight: 45, assignments: [\n          { title: 'Essay 1: Narrative', score: 34, points: 40, graded: true },\n          { title: 'Essay 2: Rhetorical Analysis', score: 27, points: 40, graded: true },\n        ]},\n        { name: 'Discussions', weight: 25, assignments: [\n          { title: 'Discussion 1', score: 8, points: 10, graded: true },\n          { title: 'Chapter 6 Discussion', points: 10, graded: false },\n          { title: 'Discussion 3', score: 7, points: 10, graded: true },\n        ]},\n        { name: 'Homework', weight: 30, assignments: [\n          { title: 'Reading Log 1', score: 8, points: 10, graded: true },\n          { title: 'Reading Log 2', score: 7, points: 10, graded: true },\n          { title: 'Reading Log 3', score: 9, points: 10, graded: true },\n        ]},\n      ]},\n      ushistory: { categories: [\n        { name: 'Tests', weight: 40, assignments: [\n          { title: 'Unit 1 Test', score: 46, points: 50, graded: true },\n          { title: 'Unit 2 Test', score: 45, points: 50, graded: true },\n        ]},\n        { name: 'Essays', weight: 30, assignments: [\n          { title: 'DBQ Essay', score: 36, points: 40, graded: true },\n          { title: 'Reading Response', points: 40, graded: false },\n        ]},\n        { name: 'Homework', weight: 30, assignments: [\n          { title: 'Source Analysis 1', score: 9, points: 10, graded: true },\n          { title: 'Source Analysis 2', score: 9, points: 10, graded: true },\n          { title: 'Source Analysis 3', score: 10, points: 10, graded: true },\n        ]},\n      ]},\n      spanish3: { categories: [\n        { name: 'Tests', weight: 35, assignments: [\n          { title: 'Unit 2 Test', score: 40, points: 50, graded: true },\n          { title: 'Unit 3 Test', score: 43, points: 50, graded: true },\n        ]},\n        { name: 'Quizzes', weight: 30, assignments: [\n          { title: 'Vocab Quiz 4', score: 8, points: 10, graded: true },\n          { title: 'Vocab Quiz 5', score: 9, points: 10, graded: true },\n          { title: 'Vocab Worksheet', points: 10, graded: false },\n        ]},\n        { name: 'Homework', weight: 35, assignments: [\n          { title: 'Workbook Ch. 5', score: 9, points: 10, graded: true },\n          { title: 'Workbook Ch. 6', score: 8, points: 10, graded: true },\n          { title: 'Workbook Ch. 7', score: 8, points: 10, graded: true },\n        ]},\n      ]},\n      pe: { categories: [\n        { name: 'Participation', weight: 40, assignments: [\n          { title: 'Week 1', score: 10, points: 10, graded: true },\n          { title: 'Week 2', score: 10, points: 10, graded: true },\n          { title: 'Week 3', score: 9, points: 10, graded: true },\n        ]},\n        { name: 'Skills Tests', weight: 25, assignments: [\n          { title: 'Fitness Test', score: 47, points: 50, graded: true },\n          { title: 'Unit Skills Check', score: 49, points: 50, graded: true },\n        ]},\n        { name: 'Homework', weight: 15, assignments: [\n          { title: 'Wellness Log', score: 10, points: 10, graded: true },\n          { title: 'Reflection', score: 9, points: 10, graded: true },\n        ]},\n        // Demonstrated Skills — kept in sync with /gradebook's own\n        // GRADEBOOK.pe (see that file for the full rationale comment):\n        // per Martin's correction (2026-08-31) this is a normal weighted\n        // category, not a separate track, so it flows straight into this\n        // page's own Grade Calculator for PE like any other category.\n        // The other three PE categories' weights were scaled down from\n        // 50/30/20 to make room for this one at 20%. Scored out of 5, not\n        // 10 (corrected 2026-09-01 per Martin's real Schoology screenshot\n        // showing skill items as normal small-point scored assignments).\n        // The qualitative Demonstrated/Developing/Not Yet rubric label\n        // (the `status` field, and the SKILL_LABEL lookup that rendered\n        // it) was removed the same day — per Martin, real Schoology\n        // doesn't expose that wording, only the score. The teacher `note`\n        // field these rows used to also carry (rendered as a sub-line in\n        // /gradebook's read-only view) was removed 2026-09-01 too,\n        // also per Martin — kept in sync with /gradebook's own data.\n        { name: 'Demonstrated Skills', weight: 20, assignments: [\n          { title: 'Teamwork & Communication', score: 5, points: 5, graded: true },\n          { title: 'Sportsmanship', score: 5, points: 5, graded: true },\n          { title: 'Skill Execution', score: 4, points: 5, graded: true },\n          { title: 'Effort & Participation', score: 5, points: 5, graded: true },\n          { title: 'Safety Awareness', score: 3, points: 5, graded: true },\n        ]},\n      ]},\n    };\n\n    // A/B/C/D/F color coding (2026-08-31, per Martin's request) — each\n    // letter tier gets its own distinct color instead of the old 3-way\n    // good/mid/bad grouping. GRADE_COLOR is the single source of truth\n    // for both the CSS class (gradeBand) and the Calculator hero\n    // letter's inline-style color.\n    // Signed in with real data (2026-10-06). A demo sign-in also has\n    // __AVERAGES__ (with an empty bundle) and shows the samples, like the preview.\n    const AV_LIVE = !!(window.__AVERAGES__ && window.__AVERAGES__.data) && window.__AVERAGES__.mode !== 'demo';\n    const AV_DATA = AV_LIVE ? window.__AVERAGES__.data : {};\n    // GRADEBOOK signed in is the bundle's, never the samples; each entry is\n    // tidied once so nothing below meets a missing number.\n    if (AV_LIVE) {\n      if (!AV_DATA.GRADEBOOK || typeof AV_DATA.GRADEBOOK !== 'object') Object.keys(GRADEBOOK).forEach(k => { delete GRADEBOOK[k]; });\n      Object.keys(GRADEBOOK).forEach(k => {\n        const entry = GRADEBOOK[k];\n        const cats = entry && Array.isArray(entry.categories) ? entry.categories : [];\n        GRADEBOOK[k] = { categories: cats.filter(c => c && typeof c === 'object').map(c => ({\n          name: String(c.name || 'Category'),\n          weight: Number(c.weight) > 0 ? Number(c.weight) : 0,\n          assignments: (Array.isArray(c.assignments) ? c.assignments : []).filter(a => a && typeof a === 'object').map(a => {\n            const n = a.score === '' || a.score === null || a.score === undefined ? NaN : Number(a.score);\n            const score = isFinite(n) ? n : undefined;\n            return { title: String(a.title || 'Untitled'), score, points: Number(a.points) > 0 ? Number(a.points) : 0, graded: !!a.graded && score !== undefined, id: a.id };\n          }),\n        })) };\n      });\n    }\n    // A weighted class leaves 0-weight categories out (\"No category\", say);\n    // a class with no weights at all counts every point (2026-10-06).\n    function gbWeighted(gb) { return !!gb && Array.isArray(gb.categories) && gb.categories.some(c => Number(c.weight) > 0); }\n    function gbWeightLabel(cat, weighted) {\n      if (Number(cat.weight) > 0) return `${cat.weight}% of grade`;\n      return weighted ? 'Not counted' : 'Counts by points';\n    }\n\n    const GRADE_COLOR = { a: 'var(--grade-good)', b: 'var(--grade-b)', c: 'var(--grade-mid)', d: 'var(--grade-d)', f: 'var(--grade-bad)' };\n    function gradeBand(letter) {\n      const l = letter[0];\n      if (l === 'A') return 'a';\n      if (l === 'B') return 'b';\n      if (l === 'C') return 'c';\n      if (l === 'D') return 'd';\n      return 'f';\n    }\n    // Standard 10-point scale, used to turn a computed percentage (e.g.\n    // from the Calculator's live recompute) back into a letter grade —\n    // COURSES' own grade/pct pairs were hand-set to plausible values\n    // rather than derived from this, so this is only used for numbers\n    // this page itself computes.\n    function letterFromPct(pct) {\n      if (pct >= 97) return 'A+';\n      if (pct >= 93) return 'A';\n      if (pct >= 90) return 'A-';\n      if (pct >= 87) return 'B+';\n      if (pct >= 83) return 'B';\n      if (pct >= 80) return 'B-';\n      if (pct >= 77) return 'C+';\n      if (pct >= 73) return 'C';\n      if (pct >= 70) return 'C-';\n      if (pct >= 67) return 'D+';\n      if (pct >= 63) return 'D';\n      if (pct >= 60) return 'D-';\n      return 'F';\n    }\n    const TREND_ARROW = { up: '↗', down: '↘', flat: '–' };\n\n    // ------------------------------------------------------------------\n    // Estimated GPA (2026-09-01, per Martin) — standard unweighted 4.0\n    // scale, averaged across every course's current letter grade\n    // (COURSES[].grade — not the predicted grade, since GPA reflects\n    // what's actually on the books). gpaColor uses roughly the same\n    // cutoffs as the A/B/C/D/F letter bands above so the number reads\n    // consistently with the rest of the page's red-through-green coloring.\n    // ------------------------------------------------------------------\n    const GPA_SCALE = {\n      'A+': 4.0, 'A': 4.0, 'A-': 3.7,\n      'B+': 3.3, 'B': 3.0, 'B-': 2.7,\n      'C+': 2.3, 'C': 2.0, 'C-': 1.7,\n      'D+': 1.3, 'D': 1.0, 'D-': 0.7,\n      'F': 0.0,\n    };\n    // Only classes with a letter grade count: a class with nothing graded\n    // (\"—\") isn't an F. None at all: no GPA (2026-10-06).\n    function computeGPA() {\n      const graded = COURSES.filter(c => GPA_SCALE[c.grade] !== undefined);\n      if (!graded.length) return null;\n      return graded.reduce((sum, c) => sum + GPA_SCALE[c.grade], 0) / graded.length;\n    }\n    function gpaColor(gpa) {\n      if (gpa >= 3.7) return 'var(--grade-good)';\n      if (gpa >= 3.0) return 'var(--grade-b)';\n      if (gpa >= 2.3) return 'var(--grade-mid)';\n      if (gpa >= 1.7) return 'var(--grade-d)';\n      return 'var(--grade-bad)';\n    }\n    function renderGPA() {\n      const gpa = computeGPA();\n      const gpaValueEl = document.getElementById('gpaValue');\n      gpaValueEl.textContent = gpa === null ? '—' : gpa.toFixed(2);\n      gpaValueEl.style.color = gpa === null ? '' : gpaColor(gpa);\n    }\n\n    // ------------------------------------------------------------------\n    // Predicted-grade reasoning popup — ported verbatim from\n    // /courses//home.\n    // ------------------------------------------------------------------\n    function niceBounds(values) {\n      const min = Math.min(...values), max = Math.max(...values);\n      let lo = Math.floor((min - 6) / 10) * 10;\n      let hi = Math.ceil((max + 6) / 10) * 10;\n      lo = Math.max(0, lo);\n      hi = Math.min(100, hi);\n      if (hi - lo < 20) { hi = Math.min(100, lo + 20); }\n      return [lo, hi];\n    }\n\n    // Grades given on the same day become one point: their average, with\n    // the date labeled \"Aug 18 ×3\" (2026-10-01). Otherwise three grades on\n    // one day drew as a zigzag across three fake \"days\".\n    function groupSameDay(h) {\n      const days = [];\n      h.points.forEach((p, i) => {\n        const d = h.dates[i];\n        const last = days[days.length - 1];\n        if (last && last.date === d) { last.sum += p; last.n++; }\n        else days.push({ date: d, sum: p, n: 1 });\n      });\n      return Object.assign({}, h, {\n        points: days.map(x => Math.round(x.sum / x.n)),\n        dates: days.map(x => x.n > 1 ? `${x.date} ×${x.n}` : x.date),\n      });\n    }\n    function buildGradeChartSVG(course) {\n      if (!HISTORY[course.id] || !Array.isArray(HISTORY[course.id].points) || !HISTORY[course.id].points.length) return '<p class=\"trend-note\">No graded work yet. The trend shows up after the first grades.</p>';\n      const hist = groupSameDay(HISTORY[course.id]);\n      const allLabels = hist.dates.concat(['Predicted']);\n      const allValues = hist.points.concat([course.predictedPct]);\n      const [yLo, yHi] = niceBounds(allValues);\n\n      const W = 240, H = 108;\n      const padL = 26, padR = 6, padT = 10, padB = 16;\n      const plotW = W - padL - padR, plotH = H - padT - padB;\n\n      const xFor = i => padL + (i / (allLabels.length - 1)) * plotW;\n      const yFor = v => padT + plotH - ((v - yLo) / (yHi - yLo)) * plotH;\n\n      const yTicks = [yLo, Math.round((yLo + yHi) / 2), yHi];\n      const gridlines = yTicks.map(t => `\n        <line x1=\"${padL}\" x2=\"${W - padR}\" y1=\"${yFor(t)}\" y2=\"${yFor(t)}\" stroke=\"var(--border)\" stroke-width=\"1\"/>\n        <text x=\"${padL - 6}\" y=\"${yFor(t) + 3}\" text-anchor=\"end\" font-size=\"8\" fill=\"var(--text-faint)\">${t}%</text>\n      `).join('');\n\n      const actualPts = hist.points.map((v, i) => [xFor(i), yFor(v)]);\n      const actualLine = actualPts.map(p => p.join(',')).join(' ');\n      const actualMarkers = actualPts.map(([x, y]) => `\n        <circle cx=\"${x}\" cy=\"${y}\" r=\"4\" fill=\"${escapeHtml(course.color)}\" stroke=\"var(--panel-bg)\" stroke-width=\"2\"/>\n      `).join('');\n\n      const predX = xFor(allLabels.length - 1), predY = yFor(course.predictedPct);\n      const lastActual = actualPts[actualPts.length - 1];\n\n      const predictedBand = `x=\"${lastActual[0]}\" y=\"${padT}\" width=\"${predX - lastActual[0]}\" height=\"${plotH}\"`;\n      const stripeDefs = `\n        <pattern id=\"predStripesGrades\" patternUnits=\"userSpaceOnUse\" width=\"6\" height=\"6\" patternTransform=\"rotate(45)\">\n          <rect width=\"6\" height=\"6\" fill=\"${escapeHtml(course.color)}\" fill-opacity=\"0.08\"/>\n          <line x1=\"0\" y1=\"0\" x2=\"0\" y2=\"6\" stroke=\"${escapeHtml(course.color)}\" stroke-width=\"2.2\"/>\n        </pattern>\n      `;\n\n      const xLabels = allLabels.map((lab, i) => `\n        <text x=\"${xFor(i)}\" y=\"${H - 2}\" text-anchor=\"middle\" font-size=\"7.5\" fill=\"var(--text-faint)\">${escapeHtml(lab === 'Predicted' ? 'Pred.' : lab)}</text>\n      `).join('');\n\n      return `\n        <svg viewBox=\"0 0 ${W} ${H}\" width=\"${W}\" height=\"${H}\" role=\"img\" aria-label=\"Line chart of ${escapeHtml(course.name)} assignment scores trending toward a predicted grade of ${escapeHtml(course.predictedPct)} percent\">\n          <defs>${stripeDefs}</defs>\n          ${gridlines}\n          <rect ${predictedBand} fill=\"url(#predStripesGrades)\" stroke=\"none\"/>\n          <polyline points=\"${actualLine}\" fill=\"none\" stroke=\"${escapeHtml(course.color)}\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>\n          <line x1=\"${lastActual[0]}\" y1=\"${lastActual[1]}\" x2=\"${predX}\" y2=\"${predY}\" stroke=\"${escapeHtml(course.color)}\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-dasharray=\"3 3\"/>\n          ${actualMarkers}\n          <circle cx=\"${predX}\" cy=\"${predY}\" r=\"4.5\" fill=\"var(--panel-bg)\" stroke=\"${escapeHtml(course.color)}\" stroke-width=\"2\"/>\n          <text x=\"${predX}\" y=\"${predY - 10}\" text-anchor=\"end\" font-size=\"8.5\" font-weight=\"800\" fill=\"var(--text-dark)\">${escapeHtml(course.predictedPct)}%</text>\n          ${xLabels}\n        </svg>\n      `;\n    }\n\n    const TREND_WORD = { up: 'Trending up', down: 'Trending down', flat: 'Holding steady' };\n\n    function renderGradePopup(course) {\n      const hist = HISTORY[course.id];\n      if (!hist || !Array.isArray(hist.points) || !hist.points.length) return `<h3>${escapeHtml(course.name)}</h3><p class=\"popup-sub\">No graded work yet. The trend and predicted grade show up after the first grades.</p>`;\n      const first = hist.points[0], lastGraded = hist.points[hist.points.length - 1];\n      return `\n        <h3>${escapeHtml(course.name)}</h3>\n        <p class=\"popup-sub\">${TREND_WORD[course.trend]}: <strong>${escapeHtml(first)}% → ${escapeHtml(lastGraded)}%</strong> over the last ${hist.points.length} graded assignments, predicting <strong>${escapeHtml(course.predictedPct)}%</strong> (${escapeHtml(course.predicted)}).</p>\n        ${buildGradeChartSVG(course)}\n        <p class=\"popup-foot\">Predicted grade extrapolates this trend — not a copy of the current grade.</p>\n      `;\n    }\n\n    const gradePopup = document.getElementById('gradePopup');\n    let popupHideTimer = null;\n\n    function showGradePopup(trigger) {\n      clearTimeout(popupHideTimer);\n      const course = findCourse(trigger.dataset.course);\n      if (!course || !HISTORY[course.id]) return;\n      gradePopup.innerHTML = renderGradePopup(course);\n      gradePopup.classList.add('show');\n      trigger.setAttribute('aria-expanded', 'true');\n\n      const rect = trigger.getBoundingClientRect();\n      const popupRect = gradePopup.getBoundingClientRect();\n      let left = rect.left + rect.width / 2 - popupRect.width / 2;\n      left = Math.max(10, Math.min(left, window.innerWidth - popupRect.width - 10));\n      let top = rect.top - popupRect.height - 10;\n      if (top < 10) top = rect.bottom + 10;\n      gradePopup.style.left = `${left}px`;\n      gradePopup.style.top = `${top}px`;\n    }\n\n    function hideGradePopup() {\n      gradePopup.classList.remove('show');\n      document.querySelectorAll('.trend.has-popup[aria-expanded=\"true\"]').forEach(t => t.setAttribute('aria-expanded', 'false'));\n    }\n\n    function bindGradePopupTriggers() {\n      document.querySelectorAll('.trend.has-popup').forEach(trigger => {\n        trigger.addEventListener('mouseenter', () => showGradePopup(trigger));\n        trigger.addEventListener('focus', () => showGradePopup(trigger));\n        trigger.addEventListener('mouseleave', () => { popupHideTimer = setTimeout(hideGradePopup, 80); });\n        trigger.addEventListener('blur', hideGradePopup);\n        trigger.addEventListener('keydown', e => { if (e.key === 'Escape') { hideGradePopup(); trigger.blur(); } });\n      });\n    }\n\n    const CALC_ICON = '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><rect x=\"5\" y=\"2\" width=\"14\" height=\"20\" rx=\"2\"/><line x1=\"8\" y1=\"6\" x2=\"16\" y2=\"6\"/><line x1=\"8\" y1=\"11\" x2=\"8.01\" y2=\"11\"/><line x1=\"12\" y1=\"11\" x2=\"12.01\" y2=\"11\"/><line x1=\"16\" y1=\"11\" x2=\"16.01\" y2=\"11\"/><line x1=\"8\" y1=\"15\" x2=\"8.01\" y2=\"15\"/><line x1=\"12\" y1=\"15\" x2=\"12.01\" y2=\"15\"/><line x1=\"16\" y1=\"15\" x2=\"16.01\" y2=\"15\"/></svg>';\n\n    const gradesBody = document.getElementById('gradesBody');\n\n    function renderGradesTable() {\n      gradesBody.innerHTML = '';\n      COURSES.forEach(c => {\n        const tr = document.createElement('tr');\n        tr.dataset.id = c.id;\n        tr.tabIndex = 0;\n        tr.setAttribute('role', 'link');\n        tr.setAttribute('aria-label', `Open ${c.name}'s gradebook`);\n        tr.innerHTML = `\n          <td>\n            <div class=\"course-row\">\n              <span class=\"course-tick\" style=\"background:${escapeHtml(c.color)}\"></span>\n              <div class=\"course-row-text\">\n                <div class=\"course-row-top\">\n                  <span class=\"course-row-name\">${escapeHtml(c.name)}</span>\n                  <span class=\"course-row-code\">${escapeHtml(c.code)}</span>\n                </div>\n                <div class=\"course-row-meta\">${escapeHtml(courseMetaLine(c))}</div>\n              </div>\n            </div>\n          </td>\n          <td><span class=\"grade-val ${gradeBand(c.grade)}\">${escapeHtml(c.grade)}${c.grade === '—' ? '' : `<span class=\"grade-pct\">${escapeHtml(c.pct)}%</span>`}</span></td>\n          <td><span class=\"trend has-popup ${escapeHtml(c.trend)}\" tabindex=\"0\" role=\"button\" aria-haspopup=\"true\" aria-label=\"${c.predicted === '—' ? `${escapeHtml(c.name)} has no grades yet. Show more.` : `Why is ${escapeHtml(c.name)} predicted ${escapeHtml(c.predicted)}, ${escapeHtml(c.predictedPct)} percent? Show reasoning.`}\" data-course=\"${escapeHtml(c.id)}\"><span class=\"arrow\">${TREND_ARROW[c.trend]}</span>${escapeHtml(c.predicted)}${c.predicted === '—' ? '' : `<span class=\"grade-pct\">(${escapeHtml(c.predictedPct)}%)</span>`}</span></td>\n          <td class=\"calc-cell\" data-course=\"${escapeHtml(c.id)}\"><button class=\"calc-btn\" type=\"button\" data-course=\"${escapeHtml(c.id)}\" aria-label=\"Open the grade calculator for ${escapeHtml(c.name)}\">${CALC_ICON}Calculate</button></td>\n        `;\n        gradesBody.appendChild(tr);\n      });\n      document.getElementById('courseTotal').textContent = `${COURSES.length} total`;\n      document.getElementById('courseCountSub').textContent = `${COURSES.length} classes`;\n      bindGradePopupTriggers();\n    }\n    renderGradesTable();\n    renderGPA();\n\n    // Row click/Enter → navigate straight to that course's real Gradebook\n    // page (2026-08-31, per Martin's request: this used to pop out a\n    // read-only preview modal here; now that /gradebook is a real\n    // page, clicking a course goes there directly instead), unless the\n    // click actually landed on the Predicted popup trigger or the Grade\n    // Calculator button, which keep their own behavior instead.\n    function gradesRowNavTarget(el) {\n      if (el.closest('.trend') || el.closest('.calc-cell')) return null;\n      const row = el.closest('tr[data-id]');\n      return row ? row.dataset.id : null;\n    }\n    function goToGradebook(id) { window.location.href = `/gradebook?course=${id}`; }\n    gradesBody.addEventListener('click', e => {\n      // The whole Grade Calculator cell opens the calculator, not just its\n      // small pill button — the button alone left a lot of dead space in\n      // that column that fell through to the row's own \"open the\n      // gradebook\" click, which read as the calculator randomly\n      // redirecting instead of opening its popup (2026-09-03 fix, per\n      // Martin: \"it should bring up the pop up on that page, not\n      // redirect\").\n      const calcCell = e.target.closest('.calc-cell');\n      if (calcCell) { openCalcModal(calcCell.dataset.course); return; }\n      const id = gradesRowNavTarget(e.target);\n      if (id) goToGradebook(id);\n    });\n    gradesBody.addEventListener('keydown', e => {\n      if (e.key !== 'Enter' && e.key !== ' ') return;\n      const id = gradesRowNavTarget(e.target);\n      if (!id) return;\n      e.preventDefault();\n      goToGradebook(id);\n    });\n\n    // ------------------------------------------------------------------\n    // Modal open/close plumbing — same fade+slide pattern as\n    // /course-home's course-info pop-out. (Used to also manage a\n    // read-only Gradebook pop-out modal alongside the Calculator — that\n    // modal is gone as of 2026-08-31, see the row-click handler above;\n    // the Calculator is the only modal left on this page.)\n    // ------------------------------------------------------------------\n    const calcModal = document.getElementById('calcModal');\n    function openModal(overlay) {\n      overlay.classList.add('show');\n      document.addEventListener('keydown', escCloseHandler);\n    }\n    function closeModal(overlay) {\n      overlay.classList.remove('show');\n      document.removeEventListener('keydown', escCloseHandler);\n    }\n    function escCloseHandler(e) {\n      if (e.key === 'Escape' && calcModal.classList.contains('show')) closeModal(calcModal);\n    }\n    calcModal.addEventListener('click', e => { if (e.target === calcModal) closeModal(calcModal); });\n\n    // ------------------------------------------------------------------\n    // Final Grade Calculator — site-map.md's Final Grade Calculator,\n    // scoped into a per-course modal rather than its own route for now.\n    // State resets fresh every time it's opened for a course: `calcEdits`\n    // holds what-if scores keyed by assignment title (every assignment\n    // gets an editable input as of 2026-08-31 — see renderCalcCategories\n    // below — pre-filled with the real score for a graded one, no upper\n    // clamp so extra credit above the assignment's point value is\n    // allowed). The standalone Final Exam fields below (see\n    // calcFinalCurrent/calcFinalWant/calcFinalWeight) are their own\n    // separate calculation and aren't part of `calcEdits`.\n    // ------------------------------------------------------------------\n    const calcCloseBtn = document.getElementById('calcCloseBtn');\n    const calcCategories = document.getElementById('calcCategories');\n    const calcFinalCurrent = document.getElementById('calcFinalCurrent');\n    const calcFinalWant = document.getElementById('calcFinalWant');\n    const calcFinalWeight = document.getElementById('calcFinalWeight');\n    const calcFinalAnswer = document.getElementById('calcFinalAnswer');\n    const calcResetBtn = document.getElementById('calcResetBtn');\n    const calcHeroLabel = document.getElementById('calcHeroLabel');\n    const calcHeroLetter = document.getElementById('calcHeroLetter');\n    const calcHeroPct = document.getElementById('calcHeroPct');\n\n    let calcCourse = null;\n    let calcEdits = {};\n    // True once the user has typed into \"Current grade\" themselves — until\n    // then it stays synced to the live category-based projected grade\n    // above, same idea as an untouched per-assignment input tracking the\n    // real score.\n    let calcFinalCurrentTouched = false;\n\n    function assignKey(catName, title) { return catName + '::' + title; }\n\n    // A short muted qualifier after an assignment's title: \"(not yet\n    // graded)\" for a real ungraded item. (The Demonstrated Skills rubric-\n    // label qualifier this used to also show was removed 2026-09-01 along\n    // with the `status` field it read — see the GRADEBOOK.pe comment.)\n    function calcAssignQualifier(a) {\n      if (!a.graded) return ` <span style=\"color:var(--text-faint); font-weight:600;\">(not yet graded)</span>`;\n      return '';\n    }\n\n    // Every assignment gets an editable input now (2026-08-31, per\n    // Martin's request to be able to change any grade — not just fill in\n    // an ungraded one — to see the hypothetical effect on the overall\n    // grade). A graded assignment's input is pre-filled with its real\n    // score; an ungraded one starts blank, same as before. An untouched\n    // graded input still uses the real score in recomputeCalc() below,\n    // so opening the Calculator and not touching anything reproduces the\n    // real grade exactly.\n    function renderCalcCategories() {\n      const gb = GRADEBOOK[calcCourse.id];\n      if (!gb || !Array.isArray(gb.categories) || !gb.categories.length) { calcCategories.innerHTML = '<p class=\"calc-empty\">Nothing graded in this class yet.</p>'; return; }\n      const weighted = gbWeighted(gb);\n      calcCategories.innerHTML = gb.categories.map(cat => {\n        const rows = cat.assignments.map(a => {\n          const key = assignKey(cat.name, a.title);\n          const defaultVal = a.graded ? a.score : '';\n          const val = calcEdits[key] !== undefined ? calcEdits[key] : defaultVal;\n          return `\n            <div class=\"calc-assign-row\">\n              <span class=\"calc-assign-title\">${escapeHtml(a.title)}${calcAssignQualifier(a)}</span>\n              <span class=\"calc-assign-score\">\n                <input class=\"calc-input hyp\" type=\"number\" min=\"0\" placeholder=\"?\" value=\"${escapeHtml(val)}\" data-key=\"${escapeHtml(key)}\" data-points=\"${escapeHtml(a.points)}\" aria-label=\"Score for ${escapeHtml(a.title)}, out of ${escapeHtml(a.points)}, extra credit above ${escapeHtml(a.points)} allowed\"><span class=\"calc-out-of\">/ ${escapeHtml(a.points)}</span>\n              </span>\n            </div>\n          `;\n        }).join('');\n        return `\n          <div class=\"calc-category\">\n            <div class=\"calc-category-head\">\n              <span class=\"calc-category-name\">${escapeHtml(cat.name)}</span>\n              <span class=\"calc-category-weight\" data-base-weight=\"${escapeHtml(cat.weight)}\">${escapeHtml(gbWeightLabel(cat, weighted))}</span>\n            </div>\n            ${rows}\n          </div>\n        `;\n      }).join('');\n    }\n\n    // The category breakdown always reflects its own real weights now —\n    // the old \"scale categories down to make room for a hypothetical\n    // final\" behavior went away with the checkbox it was tied to\n    // (2026-09-01). The Final Exam section below is a separate, simpler\n    // calculation: given a current grade, a target grade, and how much\n    // the final is worth, solve for the score still needed — it doesn't\n    // feed back into the category list above.\n    function recomputeCalc() {\n      const gb = GRADEBOOK[calcCourse.id];\n      const cats = gb && Array.isArray(gb.categories) ? gb.categories : [];\n      const weighted = gbWeighted(gb);\n      let overall = 0, weightUsed = 0, allEarned = 0, allPossible = 0;\n      cats.forEach(cat => {\n        let earned = 0, possible = 0;\n        cat.assignments.forEach(a => {\n          const key = assignKey(cat.name, a.title);\n          const raw = calcEdits[key];\n          let scoreToUse = null;\n          if (raw !== undefined && raw !== '' && !isNaN(Number(raw))) {\n            scoreToUse = Number(raw);\n          } else if (a.graded) {\n            scoreToUse = a.score;\n          }\n          // else: still ungraded and no hypothetical entered — excluded,\n          // same as before (doesn't count as a zero).\n          if (scoreToUse !== null) { earned += scoreToUse; possible += a.points; }\n        });\n        // A category with nothing counted yet is left out and the other\n        // weights scale up (2026-10-05), as in Google Classroom.\n        if (possible > 0) {\n          const w = Number(cat.weight) > 0 ? Number(cat.weight) : 0;\n          overall += (earned / possible) * 100 * w; weightUsed += w;\n          allEarned += earned; allPossible += possible;\n        }\n      });\n      // Weighted: the categories with work, scaled. No weights at all (a\n      // total-points class): every point counts. Nothing counted yet: \"—\",\n      // not an F (2026-10-06).\n      const raw = weighted ? (weightUsed > 0 ? overall / weightUsed : null) : (allPossible > 0 ? (allEarned / allPossible) * 100 : null);\n      if (raw === null || !isFinite(raw)) {\n        calcHeroLetter.textContent = '—';\n        calcHeroLetter.style.color = '';\n        calcHeroPct.textContent = '';\n        calcHeroLabel.textContent = Object.keys(calcEdits).length > 0 ? 'Projected grade' : 'Current grade';\n        calcCategories.querySelectorAll('.calc-category').forEach((box, i) => {\n          const cat = cats[i];\n          if (cat) box.querySelector('.calc-category-weight').textContent = gbWeightLabel(cat, weighted);\n        });\n        if (!calcFinalCurrentTouched) calcFinalCurrent.value = '';\n        updateFinalAnswer();\n        return;\n      }\n\n      const pct = Math.max(0, Math.min(100, raw));\n      const letter = letterFromPct(pct);\n      calcHeroLetter.textContent = letter;\n      calcHeroLetter.style.color = GRADE_COLOR[gradeBand(letter)];\n      calcHeroPct.textContent = `${pct.toFixed(1)}%`;\n      // \"Current grade\" until an assignment's real score is actually\n      // edited (calcEdits empty means every input is still showing its\n      // real value) — flips to \"Projected grade\" the moment there's a\n      // hypothetical in play, per Martin.\n      calcHeroLabel.textContent = Object.keys(calcEdits).length > 0 ? 'Projected grade' : 'Current grade';\n\n      calcCategories.querySelectorAll('.calc-category').forEach((box, i) => {\n        const cat = cats[i];\n        if (cat) box.querySelector('.calc-category-weight').textContent = gbWeightLabel(cat, weighted);\n      });\n\n      // Keep \"Current grade\" synced to the live projected grade above\n      // unless the user has typed their own number in — same touched-flag\n      // idiom used for the per-assignment inputs.\n      if (!calcFinalCurrentTouched) calcFinalCurrent.value = pct.toFixed(1);\n      updateFinalAnswer();\n    }\n\n    // Final Exam mini-calculator (2026-09-01, per Martin's reference\n    // screenshot of a standalone \"Final Grade Calculator\" tool) — solves\n    // for the score needed on the final, the reverse of the category\n    // calculator above (which projects a grade forward from scores).\n    // overall = current*(1 - w) + needed*w  →  needed = (want - current*(1-w)) / w\n    function updateFinalAnswer() {\n      const current = Number(calcFinalCurrent.value);\n      const wantRaw = calcFinalWant.value;\n      const weight = Math.max(1, Math.min(100, Number(calcFinalWeight.value) || 0));\n      if (wantRaw === '' || isNaN(current) || isNaN(weight)) {\n        calcFinalAnswer.textContent = '';\n        return;\n      }\n      const want = Number(wantRaw);\n      if (isNaN(want)) { calcFinalAnswer.textContent = ''; return; }\n      const w = weight / 100;\n      const needed = (want - current * (1 - w)) / w;\n      if (needed > 100) {\n        const bestCase = (current * (1 - w) + 100 * w).toFixed(1);\n        calcFinalAnswer.innerHTML = `Even a perfect <strong>100%</strong> on the final won't get you to <strong>${want}%</strong> — the highest you could reach is <strong>${bestCase}%</strong>.`;\n      } else if (needed <= 0) {\n        calcFinalAnswer.innerHTML = `You're already there — even a <strong>0%</strong> on the final keeps you at or above <strong>${want}%</strong>.`;\n      } else {\n        calcFinalAnswer.innerHTML = `You need <strong>${needed.toFixed(1)}%</strong> on the final exam to get <strong>${want}%</strong> in the class.`;\n      }\n    }\n\n    function openCalcModal(courseId) {\n      const course = findCourse(courseId);\n      if (!course) return;\n      calcCourse = course;\n      calcEdits = {};\n      calcFinalCurrentTouched = false;\n      calcFinalWant.value = '';\n      calcFinalWeight.value = 20;\n      document.getElementById('calcCourseName').textContent = course.name;\n      renderCalcCategories();\n      recomputeCalc();\n      openModal(calcModal);\n    }\n    calcCloseBtn.addEventListener('click', () => closeModal(calcModal));\n\n    calcCategories.addEventListener('input', e => {\n      const input = e.target.closest('.calc-input');\n      if (!input) return;\n      const key = input.dataset.key;\n      // No upper clamp (2026-09-01, per Martin: some teachers give extra\n      // credit, so a hypothetical score can legitimately exceed the\n      // assignment's own point value) — only floor at 0.\n      let val = input.value;\n      if (val !== '' && Number(val) < 0) { val = '0'; input.value = val; }\n      calcEdits[key] = val;\n      recomputeCalc();\n    });\n\n    calcFinalCurrent.addEventListener('input', () => { calcFinalCurrentTouched = true; updateFinalAnswer(); });\n    calcFinalWant.addEventListener('input', updateFinalAnswer);\n    calcFinalWeight.addEventListener('input', updateFinalAnswer);\n\n    calcResetBtn.addEventListener('click', () => {\n      calcEdits = {};\n      calcFinalCurrentTouched = false;\n      calcFinalWant.value = '';\n      calcFinalWeight.value = 20;\n      renderCalcCategories();\n      recomputeCalc();\n    });\n\n    // Nav — Home/Courses/Assignments are real pages now; Calendar/\n    // Messages/Settings stay visual-only placeholders, same convention\n    // used everywhere else in the app.\n    document.querySelectorAll('.nav-link').forEach(link => {\n      link.addEventListener('click', () => {\n        if (link.dataset.href) { window.location.href = link.dataset.href; return; }\n        document.querySelectorAll('.nav-link').forEach(l => l.classList.remove('active'));\n        link.classList.add('active');\n      });\n    });\n\n    // ------------------------------------------------------------------\n    // Profile menu — same behavior as every other page.\n    // ------------------------------------------------------------------\n    const profileBtn = document.getElementById('profileBtn');\n    // Shared profile photo/name (2026-09-07) — /settings's Edit\n    // Profile modal is the only place this is ever set, but every other\n    // page's top-right profile button used to just show a fixed \"M\" no\n    // matter what was saved there: the button never read anything back,\n    // so a photo you set in Settings was invisible the moment you left\n    // it. schoolagy_profile is the same localStorage record\n    // /settings writes on every save; this is read-only here.\n    (function () {\n      var profile = null;\n      try {\n        var raw = localStorage.getItem('schoolagy_profile');\n        if (raw) profile = JSON.parse(raw);\n      } catch (e) {}\n      if (!profile) return;\n      if (profile.photo) {\n        profileBtn.style.backgroundImage = 'url(\"' + profile.photo + '\")';\n        profileBtn.style.backgroundSize = 'cover';\n        profileBtn.style.backgroundPosition = 'center';\n        profileBtn.textContent = '';\n      } else if (profile.name) {\n        profileBtn.textContent = profile.name.trim().charAt(0).toUpperCase() || 'M';\n      }\n    })();\n    const profileMenu = document.getElementById('profileMenu');\n    function openProfileMenu() { profileMenu.hidden = false; profileBtn.setAttribute('aria-expanded', 'true'); }\n    function closeProfileMenu() { profileMenu.hidden = true; profileBtn.setAttribute('aria-expanded', 'false'); }\n    profileBtn.addEventListener('click', () => { if (profileMenu.hidden) openProfileMenu(); else closeProfileMenu(); });\n    document.addEventListener('click', e => { if (!profileMenu.hidden && !e.target.closest('.profile-menu-wrap')) closeProfileMenu(); });\n    document.addEventListener('keydown', e => { if (e.key === 'Escape' && !profileMenu.hidden) { closeProfileMenu(); profileBtn.focus(); } });\n    profileMenu.querySelectorAll('.profile-menu-item').forEach(item => {\n      item.addEventListener('click', () => {\n        if (item.dataset.action === 'settings') { window.location.href = '/settings'; return; }\n        closeProfileMenu();\n      });\n    });\n  \n\n\n    // Back link (2026-10-01, per Martin: \"where it returns to ... is always\n    // wrong\"). Every page records itself in a short per-tab trail; a page's\n    // back link then says and goes to the page before it (\"Back to AP\n    // Chemistry Hub\", \"Back to Grades\"...). With no trail (the page was\n    // opened directly) the page's own default back link is left alone.\n    (function () {\n      const SELF = '/grades';\n      const KEY = 'averages_nav_trail';\n      const here = SELF + location.search;\n      const label = (document.title || '').replace(/^Averages\\s*[—-]\\s*/, '') || 'Grades';\n      let trail = [];\n      try { trail = JSON.parse(sessionStorage.getItem(KEY) || '[]'); } catch {}\n      if (!Array.isArray(trail)) trail = [];\n      const last = trail[trail.length - 1];\n      if (last && last.href === here) last.label = label;                 // reload\n      else if (trail.length > 1 && trail[trail.length - 2].href === here) { trail.pop(); trail[trail.length - 1].label = label; } // went back\n      else trail.push({ href: here, label });\n      trail = trail.slice(-20);\n      try { sessionStorage.setItem(KEY, JSON.stringify(trail)); } catch {}\n\n      const btn = document.querySelector('.back-link');\n      const prev = trail[trail.length - 2];\n      if (!btn || !prev) return;\n      const fresh = btn.cloneNode(false);          // same button, minus old click handlers\n      fresh.removeAttribute('onclick');\n      const icon = btn.querySelector('svg');\n      if (icon) fresh.appendChild(icon.cloneNode(true));\n      const text = document.createElement('span');\n      text.textContent = 'Back to ' + prev.label;\n      fresh.appendChild(text);\n      fresh.addEventListener('click', () => { window.location.href = prev.href; });\n      btn.replaceWith(fresh);\n    })();\n  ";

export default function Page() {
  return (
    <LegacyPage
      title={TITLE}
      styleCss={STYLE_CSS}
      bodyHtml={BODY_HTML}
      scriptJs={SCRIPT_JS}
      requiresAuth={true}
      usesSavedTheme={true}
      hasUploads={false}
      externalScripts={[]}
      pageId={"grades"}
    />
  );
}
